insert into _org (seed_id, live_id) select 'b1000000-0000-4000-8000-000000000001', id from powermap.org_units where lower(name) in ('malda zone') or code = 'MZO' order by case when lower(name) = lower('Malda Zone') then 0 when code = 'MZO' then 1 else 2 end limit 1;
