-- Legacy Power Map import into powermap schema
-- Generated by scripts/import-legacy.mjs --sql
-- Run in Supabase SQL Editor after 004_powermap_schema.sql
-- Safe to re-run: soft-deletes prior SS/lines, reuses existing org_units by name.
begin;

-- Soft-delete prior network assets
update powermap.assets set is_deleted = true where is_deleted = false and asset_kind in ('substation','line','tap_node','tap_lateral');

-- Voltage lookup by code (004 may use different uuids)
create temporary table _vl (code text primary key, id uuid not null);

-- Map seed org ids → live org_units (by name / code). Do NOT re-insert MZO etc.
create temporary table _org (seed_id uuid primary key, live_id uuid not null);

